"""Validate SQL generated by the AI before it ever touches the database.

The AI's output is untrusted input. This module parses it with sqlglot and accepts only a
single, read-only SELECT (CTEs and set operations such as UNION are fine) that doesn't
reference service tables, then rewrites its LIMIT to respect `max_rows`.

The read-only SQLite connection (`query_service`) is a second, independent line of defense:
even a bug here can't turn into a write.
"""

from dataclasses import dataclass

import sqlglot
from sqlglot import exp

from app.errors import AppError, ErrorCode
from app.services.schema_service import is_service_table

# Node types that must never appear anywhere in the parsed statement. The root-type check
# below already excludes top-level DML/DDL, but sqlglot's grammar is permissive about what
# can nest where, so this walks the whole tree as a second check.
_FORBIDDEN_NODE_TYPES: tuple[type[exp.Expression], ...] = (
    exp.Insert,
    exp.Update,
    exp.Delete,
    exp.Drop,
    exp.Create,
    exp.Alter,
    exp.Attach,
    exp.Pragma,
    exp.Command,  # catches statements sqlglot has no dedicated node for (VACUUM, REINDEX, ...)
)


@dataclass
class PreparedQuery:
    sql: str
    # Rows beyond this count were cut off by our policy limit, not asked for by the query
    # itself, so the caller should report them as truncated.
    display_limit: int


def validate_and_prepare(sql: str, max_rows: int) -> PreparedQuery:
    """Validate `sql` and return it with a row limit enforced.

    Raises AppError(SQL_NOT_ALLOWED) for anything but a single read-only SELECT: multiple
    statements, writes, or references to service tables (`_columns_meta` and friends).
    """
    sql = sql.strip()
    if not sql:
        raise AppError(ErrorCode.SQL_NOT_ALLOWED, "Empty SQL query", 400)

    try:
        statements = [s for s in sqlglot.parse(sql, read="sqlite") if s is not None]
    except sqlglot.errors.SqlglotError as exc:
        raise AppError(ErrorCode.SQL_NOT_ALLOWED, f"Could not parse SQL: {exc}", 400) from exc

    if len(statements) != 1:
        raise AppError(ErrorCode.SQL_NOT_ALLOWED, "Exactly one SQL statement is allowed", 400)

    statement = statements[0]
    # exp.Query is the common base of Select, Union, Intersect and Except: plain SELECTs,
    # CTEs (they attach to the Select itself) and set operations between SELECTs, nothing else.
    if not isinstance(statement, exp.Query):
        raise AppError(ErrorCode.SQL_NOT_ALLOWED, "Only SELECT statements are allowed", 400)

    for node in statement.walk():
        if isinstance(node, _FORBIDDEN_NODE_TYPES):
            raise AppError(
                ErrorCode.SQL_NOT_ALLOWED, "Only read-only SELECT statements are allowed", 400
            )

    for table in statement.find_all(exp.Table):
        if is_service_table(table.name):
            raise AppError(
                ErrorCode.SQL_NOT_ALLOWED, f"Table '{table.name}' is not accessible", 400
            )

    display_limit, probe_limit = _resolve_limits(statement, max_rows)
    prepared = statement.limit(probe_limit)
    return PreparedQuery(sql=prepared.sql(dialect="sqlite"), display_limit=display_limit)


def _resolve_limits(statement: exp.Query, max_rows: int) -> tuple[int, int]:
    """Decide how many rows to show and how many to actually fetch.

    If the query already carries its own limit within our policy cap, that's exactly what
    the user asked for, so we execute it as-is (display == probe, never "truncated"). If it
    has no limit, or asks for more than `max_rows`, we're the ones cutting it off, so we
    probe for one extra row to know whether more exist beyond what we display.
    """
    own_limit = _extract_limit(statement)
    if own_limit is not None and own_limit <= max_rows:
        return own_limit, own_limit
    return max_rows, max_rows + 1


def _extract_limit(statement: exp.Query) -> int | None:
    limit_node = statement.args.get("limit")
    if limit_node is None:
        return None
    try:
        return int(limit_node.expression.this)
    except (AttributeError, TypeError, ValueError):
        return None
